import { test, expect, Page } from '@playwright/test';

test.describe('Order Confirmation After Payment', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');
  });

  test('should display order confirmation page after successful payment', async () => {
    // Navigate to checkout
    await page.getByRole('button', { name: /checkout/i }).click();

    // Fill in shipping information
    await page.getByLabel(/first name/i).fill('John');
    await page.getByLabel(/last name/i).fill('Doe');
    await page.getByLabel(/email/i).fill('john.doe@example.com');
    await page.getByLabel(/address/i).fill('123 Main Street');
    await page.getByLabel(/city/i).fill('New York');
    await page.getByLabel(/state/i).fill('NY');
    await page.getByLabel(/zip code/i).fill('10001');

    // Proceed to payment
    await page.getByRole('button', { name: /continue to payment/i }).click();

    // Fill in payment information
    await page.getByLabel(/card number/i).fill('4242424242424242');
    await page.getByLabel(/expiry date/i).fill('12/25');
    await page.getByLabel(/cvc/i).fill('123');

    // Submit payment
    await page.getByRole('button', { name: /pay now/i }).click();

    // Wait for confirmation page to load
    await page.waitForURL(/.*confirmation.*/);

    // Verify confirmation page elements
    await expect(page.getByRole('heading', { name: /order confirmed/i })).toBeVisible();
    await expect(page.getByText(/thank you for your order/i)).toBeVisible();
    await expect(page.getByText(/order number/i)).toBeVisible();
  });

